#include <iostream>

class Device {
public:
    virtual void powerOn() { std::cout << "Device powering on\n"; }
    virtual ~Device() = default;
};

class Speaker : virtual public Device {
public:
    void powerOn() override { std::cout << "Speaker powering on\n"; }
};

class Microphone : virtual public Device {
public:
    void powerOn() override { std::cout << "Microphone powering on\n"; }
};

class SmartSpeaker : public Speaker, public Microphone {
public:
    void activate() {
        powerOn(); // Resolves unambiguously thanks to virtual inheritance
        std::cout << "Smart speaker activated\n";
    }
};

