5: const int SEAT_RESERVED = 1;
6: 
7: class Seat {
8: public:
9:     bool reserveIfAvailable(unsigned int& seatMask, int seatNumber) {
10:         if (!seatMask & SEAT_RESERVED) {
11:             seatMask |= SEAT_RESERVED;
12:             return true;
13:         }
14:         return false;
15:     }
16: };
17: 
18: class Flight {
19: private:
20:     std::vector<unsigned int> seatMasks;
21:     Seat seat;
22: 
23: public:
24:     Flight(int numSeats) {
25:         seatMasks.resize(numSeats, 0);
26:     }
27: 
28:     void bookSeat(int seatNumber) {
29:         if (seatNumber >= 0 && seatNumber < seatMasks.size()) {
30:             if (seat.reserveIfAvailable(seatMasks[seatNumber], seatNumber)) {
31:                 std::cout << "Seat " << seatNumber << " successfully reserved.\n";
32:             } else {
33:                 std::cout << "Seat " << seatNumber << " is already taken.\n";
34:             }
35:         } else {
36:             std::cout << "Invalid seat number: " << seatNumber << "\n";
37:         }
38:     }
39: };
40: 
41: int main() {
42:     Flight flight(5);
43: 
44:     flight.bookSeat(0);
45:     flight.bookSeat(0);
46:     flight.bookSeat(1);
47: 
48:     return 0;
49: }

