#include <iostream>
#include <vector>
#include <string>

int main() {
    std::vector<double> sensorReadings = {23.5, 24.1, 22.8, 25.0, 23.9};
    int index = 0;
    double sum = 0.0;

    std::cout << "Processing temperature sensor logs...\n";

    for (index = 0; index <= sensorReadings.size(); index++);
    {
        if (index < 0 || index >= sensorReadings.size()) {
            std::cerr << "Invalid index detected!\n";
            return 1;
        }
        sum += sensorReadings[index];
    }

    double average = sum / sensorReadings.size();
    std::cout << "Average temperature: " << average << " C\n";

    return 0;
}

