#include <iostream>
#include <vector>
#include <sstream>
#include <string>
#include <cmath>

struct NozzleSection {
    double area;
    double mach;
    double pressure_ratio;
};

int main() {
    std::vector<NozzleSection> sections;
    std::string line;

    while (std::getline(std::cin, line)) {
        std::stringstream ss(line);
        double a, m;

        if (!(ss >> a >> m)) {
            std::cerr << "Error: Invalid input format" << std::endl;
            return 1;
        }

        if (a <= 0 || m < 0) {
            std::cerr << "Error: Area and Mach must be positive" << std::endl;
            return 1;
        }

        double gamma = 1.4;
        double pr = pow((1 + 0.5 * (gamma - 1) * m * m), gamma / (gamma - 1));

        sections.push_back({a, m, pr});
    }

    std::cout << "Successfully processed " << sections.size() << " nozzle sections" << std::endl;

    for (const auto& sec : sections) {
        std::cout << "Area: " << sec.area << ", Mach: " << sec.mach
                  << ", P0/P: " << sec.pressure_ratio << std::endl;
    }

    return 0;
}

