#include <iostream>
#include <vector>
#include <string>

struct Item {
    std::string name;
    int stackCount;
    int maxStackSize;
};

void processInventory(std::vector<Item>* inventory, int startIndex) {
    if (!inventory || startIndex < 0 || startIndex >= inventory->size()) {
        std::cerr << "Error: Invalid index or null inventory\n";
        return;
    }

    for (int i = startIndex; i < inventory->size(); ++i) {
        Item& item = (*inventory)[i];
        if (item.stackCount <= 0) {
            continue;
        }
        int transferAmount = std::min(5, item.maxStackSize - item.stackCount);
        item.stackCount += transferAmount;
    }
}

int main() {
    std::vector<Item> playerInventory = {
        {"Health Potion", 2, 10},
        {"Arrow", 15, 99},
        {"Gold Coin", 0, 1000},
        {"Mana Potion", 7, 10}
    };

    int lastKnownSlot = -1;

    processInventory(&playerInventory, lastKnownSlot);

    for (const auto& item : playerInventory) {
        std::cout << item.name << ": " << item.stackCount << "/" << item.maxStackSize << "\n";
    }

    return 0;
}

