1: using namespace std;
2: #include <iostream>
3: #include <cstring>
4: 
5: const int TABLE_SIZE=10;
6: 
7: struct InventoryItem {
8:     char* name;
9:     int quantity;
10:     InventoryItem* next;
11: };
12: 
13: class InventorySystem {
14:     InventoryItem* table[TABLE_SIZE];
15: 
16:     int hash(const char* name)
17: {
18:         int sum=0;
19:         for (int i=0; name[i] != '\0'; ++i)
20: {
21:             sum += name[i];
22:         }
23:         return sum % TABLE_SIZE;
24:     }
25: 
26: public:
27:     InventorySystem()
28: {
29:         for (int i=0; i<TABLE_SIZE; ++i)
30: {
31:             table[i]=nullptr;
32:         }
33:     }
34: 
35:     void addItem(char* name, int quantity)
36: {
37:         int index=hash(name);
38:         InventoryItem* newItem=new InventoryItem;
39:         newItem->name=name;
40:         newItem->quantity=quantity;
41:         newItem->next=table[index];
42:         table[index]=newItem;
43:     }
44: 
45:     void renameItem(const char* oldName, const char* newName)
46: {
47:         int index=hash(oldName);
48:         InventoryItem* current=table[index];
49:         while (current != nullptr)
50: {
51:             if (strcmp(current->name, oldName)==0)
52: {
53:                 // Attempting to modify the string in place
54:                 strcpy(current->name, newName);
55:                 return;
56:             }
57:             current=current->next;
58:         }
59:     }
60: 
61:     void display()
62: {
63:         for (int i=0; i<TABLE_SIZE; ++i)
64: {
65:             InventoryItem* current=table[i];
66:             while (current != nullptr)
67: {
68:                 cout << "Item: " << current->name << ", Quantity: " << current->quantity << endl;
69:                 current=current->next;
70:             }
71:         }
72:     }
73: 
74:     ~InventorySystem()
75: {
76:         for (int i=0; i<TABLE_SIZE; ++i)
77: {
78:             InventoryItem* current=table[i];
79:             while (current != nullptr)
80: {
81:                 InventoryItem* temp=current;
82:                 current=current->next;
83:                 delete temp;
84:             }
85:         }
86:     }
87: };
88: 
89: int main()
90: {
91:     InventorySystem inv;
92:     inv.addItem(const_cast<char*>("sword"), 2);
93:     inv.addItem(const_cast<char*>("shield"), 1);
94:     inv.renameItem("sword", "great_sword");
95:     inv.display();
96:     return 0;
97: }

