#include <iostream>
#include <vector>
#include <sstream>
#include <string>
#include <iomanip>

struct TrafficLight {
    std::string intersection;
    int greenDuration;
    int yellowDuration;
    int redDuration;
};

bool parseLightConfig(const std::string& line, TrafficLight& light) {
    std::stringstream ss(line);
    std::string inter;
    int green, yellow, red;

    if (!(ss >> inter >> green >> yellow >> red)) {
        return false;
    }

    if (green <= 0 || yellow <= 0 || red <= 0) {
        return false;
    }

    light.intersection = inter;
    light.greenDuration = green;
    light.yellowDuration = yellow;
    light.redDuration = red;

    return true;
}

int main() {
    std::vector<TrafficLight> lights;
    std::string line;

    std::cout << "Enter traffic light configurations (intersection green yellow red):\n";
    std::cout << "(Press Ctrl+D or type empty line to finish)\n";

    while (std::getline(std::cin, line) && !line.empty()) {
        TrafficLight light;
        if (parseLightConfig(line, light)) {
            lights.push_back(light);
        } else {
            std::cout << "Warning: Invalid format or non-positive durations in line: '" << line << "'\n";
        }
    }

    if (lights.empty()) {
        std::cout << "No valid traffic light configurations entered.\n";
        return 1;
    }

    std::cout << "\n--- Simulated Traffic Light Timings ---\n";
    for (const auto& light : lights) {
        int cycle = light.greenDuration + light.yellowDuration + light.redDuration;
        std::cout << std::left << std::setw(15) << light.intersection
                  << " | Cycle: " << cycle << "s (G:" << light.greenDuration
                  << "s, Y:" << light.yellowDuration << "s, R:" << light.redDuration << "s)\n";
    }

    return 0;
}

