#include <iostream>
#include <vector>
#include <string>
#include <cctype>

struct Nucleotide {
    char base;
    int quality_score;
};

bool isValidBase(char b) {
    return b == 'A' || b == 'T' || b == 'C' || b == 'G';
}

std::vector<Nucleotide> decodeDNA(const std::vector<std::string>& rawReads) {
    std::vector<Nucleotide> cleanSeq;

    for (size_t i = 0; i < rawReads.size(); ++i) {
        std::string read = rawReads[i];

        if (read.empty()) continue;

        char potentialBase = std::toupper(read[0]);
        int q = read.size() > 1 ? (int)read[1] : 0;

        if (isValidBase(potentialBase)) {
            Nucleotide nt = {potentialBase, q};
            cleanSeq.push_back(nt);
        }
    }

    return cleanSeq;
}

int main() {
    std::vector<std::string> corruptedData = {"a3", "x", "G", "t7", "", "C$", "n", "A"};

    std::vector<Nucleotide> result = decodeDNA(corruptedData);

    if (result.empty()) {
        std::cout << "No valid nucleotides found.\n";
        return 1;
    }

    std::cout << "Decoded sequence: ";
    for (size_t j = 0; j < result.size(); ++j) {
        std::cout << result[j].base;
    }
    std::cout << "\nQuality scores: ";
    for (size_t k = 0; k < result.size(); ++k) {
        std::cout << (int)result[k].quality_score;
        if (k != result.size() - 1) std::cout << ", ";
    }
    std::cout << "\n";

    return 0;
}

