#include <iostream>
#include <vector>
#include <string>

struct TaxBracket {
    double min;
    double max;
    double rate;
};

int main() {
    std::vector<TaxBracket> brackets = {
        {0.0, 10000.0, 0.10},
        {10000.0, 30000.0, 0.15},
        {30000.0, 60000.0, 0.25},
        {60000.0, -1.0, 0.35}  // -1.0 means no upper limit
    };

    double income = 0;
    std::cout << "Enter annual income: ";
    std::cin >> income;

    if (std::cin.fail()) {
        std::cout << "Error: Invalid input.\n";
        return 1;
    }

    if (income < 0) {
        std::cout << "Error: Income cannot be negative.\n";
        return 1;
    }

    double total_tax = 0.0;
    bool applied = false;

    for (size_t i = 0; i < brackets.size(); ++i) {
        double lower = brackets[i].min;
        double upper = brackets[i].max;
        double rate = brackets[i].rate;

        if (income > lower || (income == 0 && lower == 0)) {
            double taxable_in_band = 0;
            if (upper < 0) {
                taxable_in_band = income - lower;
                total_tax += taxable_in_band * rate;
                applied = true;
                break;
            } else if (income > upper) {
                taxable_in_band = upper - lower;
            } else {
                taxable_in_band = income - lower;
            }
            total_tax += taxable_in_band * rate;
            applied = true;
        }
    }

    if (!applied) {
        total_tax = 0.0;
    }

    std::cout.precision(2);
    std::cout << std::fixed;
    std::cout << "Total tax owed: $" << total_tax << std::endl;

    return 0;
}

