#include <iostream>
#include <vector>
#include <string>
#include <cctype>

struct Nucleotide {
    char base;
    int quality_score;
};

bool isValidBase(char b) {
    return b == 'A' || b == 'T' || b == 'C' || b == 'G';
}

std::vector<Nucleotide> decodeDNA(const std::vector<std::string>& raw_reads) {
    std::vector<Nucleotide> result;

    for (size_t i = 0; i < raw_reads.size(); ++i) {
        std::string line = raw_reads[i];

        for (size_t j = 0; j < line.size(); ++j) {
            char c = std::toupper(line[j]);

            if (isValidBase(c)) {
                Nucleotide nt;
                nt.base = c;
                nt.quality_score = (j % 93) + 10; // Simulated quality score
                result.push_back(nt);
            }
        }
    }

    return result;
}

int main() {
    std::vector<std::string> corruptedData = {
        "aTgC!nNx",
        "tttAAAGGG",
        "cgxT!A@C",
        "NNNNNN",
        "atcg"
    };

    std::vector<Nucleotide> cleanSeq = decodeDNA(corruptedData);

    if (cleanSeq.empty()) {
        std::cout << "No valid nucleotides found.\n";
        return 1;
    }

    std::cout << "Successfully processed " << cleanSeq.size() << " nucleotides.\n";

    for (size_t k = 0; k < cleanSeq.size() && k < 10; ++k) {
        std::cout << "Base: " << cleanSeq[k].base 
                  << ", Quality: " << cleanSeq[k].quality_score << '\n';
    }

    if (cleanSeq.size() > 10) {
        std::cout << "... and " << (cleanSeq.size() - 10) << " more.\n";
    }

    return 0;
}

