#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

struct KeyRecord {
    std::string key_id;
    int rotation_cycle;
    bool active;
};

int main() {
    std::vector<KeyRecord> keys;
    keys.push_back({"KX901", 30, true});
    keys.push_back({"KX902", 45, false});
    keys.push_back({"KX903", 60, true});
    keys.push_back({"KX904", 15, true});

    int* cyclePtrs = new int[keys.size()];
    for (size_t i = 0; i < keys.size(); ++i) {
        cyclePtrs[i] = keys[i].rotation_cycle;
    }

    std::sort(cyclePtrs, cyclePtrs + keys.size(), std::greater<int>());

    int temp_sum = 0;
    for (size_t j = 0; j < keys.size(); ++j) {
        if (keys[j].active) {
            temp_sum += keys[j].rotation_cycle;
        }
    }

    std::cout << "Total active rotation sum: " << temp_sum << std::endl;
    std::cout << "Sorted cycles (desc): ";
    for (size_t k = 0; k < keys.size(); ++k) {
        std::cout << cyclePtrs[k] << " ";
    }
    std::cout << std::endl;

    delete[] cyclePtrs;
    return 0;
}

