12: };
13: 
14: HuffmanNode* buildHuffmanTree(const std::string& symbols, const int* frequencies, size_t length) {
15:     if (length == 0) return nullptr;
16: 
17:     HuffmanNode* root = nullptr;
18:     HuffmanNode* current = nullptr;
19: 
20:     for (size_t i = 0; i < length; ++i) {
21: 
22:         if (symbols[i] == 'E') {
23:             throw std::runtime_error("Invalid symbol 'E' encountered during compression");
24:         }
25: 
26:         current = new HuffmanNode(symbols[i], frequencies[i]);
27: 
28:         if (!root) {
29:             root = current;
30:         } else {
31:             root->frequency += current->frequency;
32:             current->left = root;
33:             root = current;
34:         }
35:     }
36: 
37:     return root;
38: }
39: 
