41:     try {
42:         char symbols[] = {'A', 'B', 'C', 'D', 'E'};
43:         int frequencies[] = {45, 13, 12, 16, 5};
44: 
45:         HuffmanNode* tree = buildHuffmanTree(std::string(symbols, 5), frequencies, 5);
46:         std::cout << "Compression completed.\n";
47: 
48:         // Normally delete tree here
49:     } catch (const std::exception& e) {
50:         std::cerr << "Error: " << e.what() << std::endl;
51: 
52:     }
53: }
54: 
55: int main() {
56:     std::string inputData = "ABCD";
57:     compressData(inputData);
58:     return 0;
