#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

struct Item {
    std::string name;
    int id;
    int stack;
    bool operator==(const Item& other) const {
        return id == other.id;
    }
};

void updateInventory(std::vector<Item>* inv, int itemID, int quantity) {
    auto it = std::find_if(inv->begin(), inv->end(), [itemID](const Item& i) { return i.id == itemID; });
    if (it != inv->end()) {
        it->stack += quantity;
        if (it->stack <= 0) {
            inv->erase(it);
        }
    } else if (quantity > 0) {
        inv->push_back({"Unknown Item", itemID, quantity});
    }
}

