#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

struct Passenger {
    std::string name;
    int seatRow;
    char seatLetter;
    bool checkedIn;
};

struct Flight {
    std::string flightNum;
    int totalRows;
    char seatLayout; // e.g., 'F' for A-F
    std::vector<Passenger*> seating;
};

void assignSeat(Flight* f, int row, char letter, std::string passengerName) {
    if (row < 1 || row > f->totalRows || letter < 'A' || letter > f->seatLayout) {
        return;
    }
    int idx = (row - 1) * (f->seatLayout - 'A' + 1) + (letter - 'A');
    if (idx >= f->seating.size()) return;
    if (f->seating[idx] != nullptr) return;

    Passenger* p = new Passenger();
    p->name = passengerName;
    p->seatRow = row;
    p->seatLetter = letter;
    p->checkedIn = false;

    f->seating[idx] = p;
}

void checkInPassenger(Flight* f, int row, char letter) {
    if (row < 1 || row > f->totalRows || letter < 'A' || letter > f->seatLayout) {
        return;
    }
    int idx = (row - 1) * (f->seatLayout - 'A' + 1) + (letter - 'A');
    if (idx >= f->seating.size()) return;
    if (f->seating[idx] == nullptr) return;

    f->seating[idx]->checkedIn = true;
}

void printSeatingChart(Flight* f) {
    int seatsPerRow = f->seatLayout - 'A' + 1;
    for (int r = 0; r < f->totalRows; ++r) {
        std::cout << "Row " << (r + 1) << ": ";
        for (int s = 0; s < seatsPerRow; ++s) {
            int idx = r * seatsPerRow + s;
            if (f->seating[idx] == nullptr) {
                std::cout << "[ ] ";
            } else {
                char status = f->seating[idx]->checkedIn ? 'X' : 'O';
                std::cout << "[" << status << "] ";
            }
        }
        std::cout << "\n";
    }
}

int main() {
    Flight f;
    f.flightNum = "AA123";
    f.totalRows = 3;
    f.seatLayout = 'C';

    int seatsCount = f.totalRows * (f.seatLayout - 'A' + 1);
    f.seating.resize(seatsCount, nullptr);

    assignSeat(&f, 1, 'A', "Alice");
    assignSeat(&f, 1, 'B', "Bob");
    assignSeat(&f, 2, 'A', "Charlie");

    checkInPassenger(&f, 1, 'A');
    checkInPassenger(&f, 2, 'A');

    printSeatingChart(&f);

    // Clean up
    for (auto& p : f.seating) {
        delete p;
        p = nullptr;
    }

    return 0;
}

