5: class TrieNode {
6: public:
7:     std::vector<TrieNode*> children;
8:     bool is_end;
9:     std::string title;
10: 
11:     TrieNode() : children(26, nullptr), is_end(false), title("") {}
12: };
13: 
14: class Trie {
15: private:
16:     TrieNode* root;
17: 
18:     int charToIndex(char c) {
19:         return c - 'a';
20:     }
21: 
22: public:
23:     Trie() {
24:         root = new TrieNode();
25:     }
26: 
27:     void insert(const std::string& word) {
28:         TrieNode* curr = root;
29:         for (char c : word) {
30:             int index = charToIndex(c);
31:             if (curr->children[index] == nullptr) {
32:                 curr->children[index] = new TrieNode();
33:             }
34:             curr = curr->children[index];
35:         }
36:         curr->is_end = true;
37:         curr->title = word;
38:     }
39: 
40:     std::string search(const std::string& prefix) {
41:         TrieNode* curr = root;
42:         for (char c : prefix) {
43:             int index = charToIndex(c);
44:             if (curr->children[index] == nullptr) {
45:                 return "";
46:             }
47:             curr = curr->children[index];
48:         }
49:         if (curr->is_end) {
50:             return curr->title;
51:         }
52:         return "";
53:     }
54: };
55: 
56: int main() {
