#include <iostream>
#include <vector>
#include <string>
#include <sstream>

struct Player {
    std::string name;
    int hits;
    int atBats;
};

double calculateBattingAverage(int hits, int atBats) {
    return atBats == 0 ? 0.0 : static_cast<double>(hits) / atBats;
}

int main() {
    std::vector<Player> players;
    std::string line;

    while (std::getline(std::cin, line) && !line.empty()) {
        std::stringstream ss(line);
        Player p;
        std::string name;
        int h, ab;

        if (!(ss >> name >> h >> ab)) {
            std::cerr << "Error: Invalid input format" << std::endl;
            return 1;
        }

        p.name = name;
        p.hits = h;
        p.atBats = ab;
        players.push_back(p);
    }

    if (players.empty()) {
        std::cout << "No players processed." << std::endl;
        return 0;
    }

    std::cout.precision(3);
    for (const auto& player : players) {
        double avg = calculateBattingAverage(player.hits, player.atBats);
        std::cout << player.name << ": " << std::fixed << avg << std::endl;
    }

    return 0;
}

