#include <iostream>
#include <vector>
#include <iomanip>

struct PlayerStats {
    std::string name;
    int atBats;
    int hits;
};

double calculateBattingAverage(const PlayerStats& player) {
    if (player.atBats <= 0) {
        return 0.0;
    }
    return static_cast<double>(player.hits) / player.atBats;
}

int main() {
    std::vector<PlayerStats> players = {
        {"Alice", 50, 15},
        {"Bob", 0, 0},
        {"Charlie", 40, 10}
    };

    std::cout << std::fixed << std::setprecision(3);
    for (size_t i = 0; i < players.size(); ++i) {
        if (players[i].atBats < 0) {
            std::cerr << "Error: Invalid at-bats count for " << players[i].name << "\n";
            return 1;
        }
        double avg = calculateBattingAverage(players[i]);
        std::cout << players[i].name << ": " << avg << "\n";
    }

    return 0;
}

