#include <iostream>
#include <vector>
#include <sstream>
#include <string>
#include <cmath>

struct GPSCoordinate {
    double latitude;
    double longitude;
};

bool parseCoordinate(const std::string& line, GPSCoordinate& coord) {
    std::stringstream ss(line);
    std::string lat_str, lon_str;

    if (!(ss >> lat_str >> lon_str)) {
        return false;
    }

    try {
        coord.latitude = std::stod(lat_str);
        coord.longitude = std::stod(lon_str);
    } catch (...) {
        return false;
    }

    if (std::abs(coord.latitude) > 90.0 || std::abs(coord.longitude) > 180.0) {
        return false;
    }

    return true;
}

int main() {
    std::vector<GPSCoordinate> waypoints;
    std::string input_line;

    while (std::getline(std::cin, input_line)) {
        if (input_line.empty()) continue;

        GPSCoordinate coord;
        if (!parseCoordinate(input_line, coord)) {
            std::cerr << "Error: Invalid GPS coordinate format or value\n";
            return 1;
        }
        waypoints.push_back(coord);
    }

    if (waypoints.empty()) {
        std::cerr << "Error: No valid waypoints provided\n";
        return 1;
    }

    std::cout << "Successfully processed " << waypoints.size() << " waypoints\n";
    for (size_t i = 0; i < waypoints.size(); ++i) {
        std::cout << "Waypoint " << (i + 1) << ": (" 
                  << waypoints[i].latitude << ", " 
                  << waypoints[i].longitude << ")\n";
    }

    return 0;
}

