1: #include <iostream>
2: #include <string>
3: #include <stdexcept>
4: 
5: using namespace std;
6: 
7: class InventoryItem {
8: public:
9:     int id;
10:     string name;
11: 
12:     InventoryItem(int itemId, const string& itemName) : id(itemId), name(itemName) {}
13: };
14: 
15: class InventoryNode {
16: public:
17:     InventoryItem* item;
18:     InventoryNode* left;
19:     InventoryNode* right;
20: 
21:     InventoryNode(InventoryItem* itm) : item(itm), left(nullptr), right(nullptr) {}
22: };
23: 
24: class GameInventory {
25: private:
26:     InventoryNode* root;
27: 
28:     InventoryNode* insertRecursive(InventoryNode* node, InventoryItem* item) {
29:         if (node == nullptr) {
30:             return new InventoryNode(item);
31:         }
32: 
33:         if (item->id < node->item->id) {
34:             node->left = insertRecursive(node->left, item);
35:         } else if (item->id > node->item->id) {
36:             node->right = insertRecursive(node->right, item);
37:         }
38: 
39:         return node;
40:     }
41: 
42: public:
43:     GameInventory() : root(nullptr) {}
44: 
45:     void addItem(int id, const string& name) {
46:         if (id < 0)
47:             throw invalid_argument("Item ID cannot be negative.");
48: 
49:
50:         InventoryItem* newItem = new InventoryItem(id, name);
51: 
52:         try {
53:             if (name == "CORRUPT")
54:                 throw runtime_error("Simulated item corruption");
55: 
56:             root = insertRecursive(root, newItem);
57:         } catch (const exception& e) {
58:             cerr << "Error adding item: " << e.what() << endl;
59: 
60:             throw; 
61:         }
62:     }
63: 
64:     ~GameInventory() {
65: 
66: 
67:     }
68: };
69: 
70: int main() {
71:     GameInventory inv;
72: 
73:     try {
74:         inv.addItem(101, "Sword");
75:         inv.addItem(-5, "Shield"); 
76:     } catch (const exception&) {
77:         cout << "Caught first exception.\n";
78:     }
79: 
80:     try {
81:         inv.addItem(102, "CORRUPT");
82:     } catch (const exception&) {
83:         cout << "Caught second exception.\n";
84:     }
