#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>

struct GpsPoint {
    double lat;
    double lon;
    int id;
};

bool isValidCoord(double x) {
    return !std::isnan(x) && std::isfinite(x);
}

int main() {
    std::vector<GpsPoint> route;
    double tempLat, tempLon;
    int counter = 0;

    while (std::cin >> tempLat >> tempLon) {
        if (!isValidCoord(tempLat) || !isValidCoord(tempLon) ||
            tempLat < -90.0 || tempLat > 90.0 ||
            tempLon < -180.0 || tempLon > 180.0) {
            std::cout << "Error: Invalid coordinate at index " << counter << std::endl;
            return 1;
        }

        GpsPoint p;
        p.lat = tempLat;
        p.lon = tempLon;
        p.id = counter;
        route.push_back(p);
        counter++;
    }

    if (route.empty()) {
        std::cout << "Error: No valid coordinates provided" << std::endl;
        return 1;
    }

    double totalDist = 0.0;
    for (int i = 0; i < (int)route.size() - 1; i++) {
        double dLat = (route[i+1].lat - route[i].lat) * M_PI / 180.0;
        double dLon = (route[i+1].lon - route[i].lon) * M_PI / 180.0;
        double a = sin(dLat/2) * sin(dLat/2) +
                  cos(route[i].lat * M_PI / 180.0) * cos(route[i+1].lat * M_PI / 180.0) *
                  sin(dLon/2) * sin(dLon/2);
        double c = 2 * atan2(sqrt(a), sqrt(1-a));
        totalDist += 6371.0 * c;
    }

    std::cout << std::fixed << std::setprecision(3);
    std::cout << "Successfully processed " << counter << " waypoints" << std::endl;
    std::cout << "Total flight distance: " << totalDist << " km" << std::endl;

    return 0;
}

