4: int partition(std::vector<int>& arr, int low, int high) {
5:     int pivot = arr[high];
6:     int i = low - 1;
7:     for (int j = low; j < high; j++) {
8:         if (arr[j] <= pivot) {
9:             i++;
10:             std::swap(arr[i], arr[j]);
11:         }
12:     }
13:     std::swap(arr[i + 1], arr[high]);
14:     return i + 1;
15: }
16: 
17: void quicksort(std::vector<int>& arr, int low, int high) {
18:     if (low < high) {
19:         int pi = partition(arr, low, high);
20:         quicksort(arr, low, pi - 1);
21:         quicksort(arr, pi + 1, high);
22:     }
23: }
