25: double computeMedian(std::vector<int>& arr, int left, int right) {
26:     int size;
27:     if (left == right) {
28:         return static_cast<double>(arr[left]);
29:     }
30:     int mid = left + (right - left) / 2;
31:     if ((size % 2) == 1) {
32:         return static_cast<double>(arr[mid]);
33:     } else {
34:         return (static_cast<double>(arr[mid]) + static_cast<double>(arr[mid + 1])) / 2.0;
35:     }
36: }
