#include <iostream>
#include <vector>

int total_errors; // Global variable, zero-initialized by default

int process_sensor_logs(std::vector<int> logs) {
    int current_sum; // Local variable, NOT initialized

    for (int i = 0; i < logs.size(); ++i) {
        if (i < 0 || i >= logs.size()) {
            return 1;
        }
        current_sum += logs[i];
    }

    total_errors += 1; // Increment global counter
    std::cout << "Processed log sum: " << current_sum << std::endl;
    return 0;
}

int main() {
    std::vector<int> sensor_data = {10, 20, 30, 40, 50};
    process_sensor_logs(sensor_data);
    std::cout << "Total error count: " << total_errors << std::endl;
    return 0;
}

